import sys

def main():
    lines = sys.stdin.read().splitlines()
    status = lines[0]

    if status == "ERROR":
        message = lines[1]
        print(f"Error fetching data from the database: {message}")
    else:
        n = int(lines[1])
        if n > 10000:
            print("Warning: The data contains more than 10000 rows.")
        header = lines[2]
        print(header)
        for row in lines[3:3 + n]:
            print(row)

if __name__ == "__main__":
    main()
